"use strict";
window.STUDY = {
  source: "2025 ICF Core Competencies",
  version: "Released September 2025 · rev. 09.08.25",
  subcompetencies: {
    "1.01": "Demonstrates personal integrity and honesty in interactions with clients, sponsors and relevant stakeholders",
    "1.02": "Is sensitive to clients' identity, environment, experiences, values and beliefs",
    "1.03": "Uses language appropriate and respectful to clients, sponsors and relevant stakeholders",
    "1.05": "Maintains confidentiality with client information per stakeholder agreements and pertinent laws",
    "1.06": "Maintains the distinctions between coaching, consulting, psychotherapy and other support professions",
    "1.07": "Refers clients to other support professionals, as appropriate",
    "2.01": "Acknowledges that clients are responsible for their own choices",
    "2.02": "Engages in ongoing learning and development as a coach, including remaining aware of current coaching best practices and use of technology",
    "2.03": "Develops an ongoing reflective practice to enhance one's coaching",
    "2.04": "Remains aware of and open to the influence of biases, context and culture on self and others",
    "2.06": "Develops and maintains the ability to manage one's emotions",
    "2.07": "Maintains emotional, physical, and mental well-being in preparation for, throughout, and following each session.",
    "2.08": "Seeks help from outside sources when necessary",
    "2.09": "Nurtures openness and curiosity in oneself, the client, and the coaching process.",
    "2.10": "Remains aware of the influence of one's thoughts and behaviors on the client and others",
    "3.01": "Describes one's coaching philosophy and clearly defines what coaching is and is not for potential clients and stakeholders",
    "3.02": "Reaches agreement about what is and is not appropriate in the relationship, what is and is not being offered, and the responsibilities of the client and relevant stakeholders, including commitment to working toward coaching goals",
    "3.03": "Reaches agreement about the guidelines and specific parameters of the coaching relationship such as logistics, fees, scheduling, duration, termination, confidentiality and inclusion of others",
    "3.04": "Partners with the client and relevant stakeholders to establish an overall coaching plan and goals",
    "3.06": "Partners with the client to identify or reconfirm what they want to accomplish in the session",
    "3.07": "Partners with the client to define what the client believes they need to address or resolve to achieve what they want to accomplish in the session",
    "3.08": "Partners with the client to define or reconfirm measures of success for what the client wants to accomplish in the coaching engagement or individual session",
    "3.09": "Partners with the client to manage the time and focus of the session",
    "3.10": "Continues coaching in the direction of the client's desired outcome unless the client indicates otherwise",
    "3.12": "Revisits the coaching agreement when necessary to ensure the coaching approach is meeting the client's needs",
    "4.01": "Seeks to understand the client within their context which may include their identity, environment, experiences, values and beliefs",
    "4.02": "Demonstrates respect for the client's identity, perceptions, style and language and adapts one's coaching to the client",
    "4.03": "Acknowledges and respects the client's unique talents, insights and work in the coaching process",
    "4.04": "Shows support, empathy and concern for the client",
    "4.05": "Acknowledges and supports the client's expression of feelings, perceptions, concerns, beliefs and suggestions",
    "4.06": "Demonstrates openness and transparency as a way to display vulnerability and build trust with the client",
    "5.01": "Remains focused, observant, empathetic and responsive to the client",
    "5.02": "Demonstrates curiosity during the coaching process",
    "5.03": "Remains aware of what is emerging for self and client in the present moment",
    "5.04": "Manages one's emotions to stay present with the client",
    "5.05": "Demonstrates confidence in working with strong client emotions during the coaching process",
    "5.06": "Is comfortable working in a space of not knowing",
    "5.07": "Creates or allows space for silence, pause or reflection",
    "6.01": "Considers the client's context, identity, environment, experiences, values and beliefs to enhance understanding of what the client is communicating",
    "6.02": "Reflects or summarizes what the client is communicating to ensure clarity and understanding",
    "6.03": "Recognizes and inquires when there is more to what the client is communicating",
    "6.04": "Notices, acknowledges and explores the client's emotions, energy shifts, non-verbal cues or other behaviors",
    "6.05": "Integrates the client's words, tone of voice and body language to determine the full meaning of what the client is communicating",
    "6.06": "Notices trends in the client's behaviors and emotions across sessions to discern themes and patterns",
    "7.01": "Considers client experience when deciding what might be most useful",
    "7.03": "Asks questions about the client, such as their way of thinking, values, needs, wants and beliefs",
    "7.04": "Asks questions that help the client explore beyond current thinking",
    "7.06": "Notices what is working to enhance client progress",
    "7.07": "Adjusts the coaching approach in response to the client's needs",
    "7.08": "Helps the client identify factors that influence current and future patterns of behavior, thinking or emotion",
    "7.09": "Invites the client to generate ideas about how they can move forward and what they are willing or able to do",
    "7.10": "Supports the client in reframing perspectives",
    "7.11": "Shares observations, knowledge, and feelings, without attachment, that have the potential to create new insights for the client",
    "8.01": "Works with the client to integrate new awareness, insight or learning into their worldview and behaviors",
    "8.02": "Partners with the client to design goals, actions and accountability measures that integrate and expand new learning",
    "8.03": "Acknowledges and supports client autonomy in the design of goals, actions and methods of accountability",
    "8.04": "Supports the client in identifying potential results or learning from identified action steps",
    "8.05": "Invites the client to consider how to move forward, including resources, support and potential barriers",
    "8.06": "Partners with the client to summarize learning and insight within or between sessions",
    "8.08": "Acknowledges the client's progress and successes",
    "8.09": "Partners with the client to close the session"
  },
  competencies: [
    {id:1, title:"Demonstrates Ethical Practice", definition:"Understands and consistently applies coaching ethics and standards of coaching", group:"Foundation", summary:"Follow coaching ethics, protect the client's information and notice when they need a different kind of professional help."},
    {id:2, title:"Embodies a Coaching Mindset", definition:"Engages in ongoing personal and professional learning and development as a coach. Works with coaching supervisors or mentor coaches as needed. Develops and maintains a mindset that is open, curious, flexible and client-centered.", group:"Foundation", summary:"Keep learning and reflecting on your coaching. Notice how your assumptions and biases affect your work with clients."},
    {id:3, title:"Establishes and Maintains Agreements", definition:"Partners with the client and relevant stakeholders to create clear agreements about the coaching relationship, process, plans and goals. Establishes agreements for the overall coaching engagement as well as those for each coaching session.", group:"Co-creating the relationship", summary:"Agree with the client on what coaching will cover and what each session is for. Check the agreement again when their needs change."},
    {id:4, title:"Cultivates Trust and Safety", definition:"Partners with the client to create a safe, supportive environment that allows the client to share freely. Maintains a relationship of mutual respect and trust.", group:"Co-creating the relationship", summary:"Respect the client's experience and context so they can express themselves freely."},
    {id:5, title:"Maintains Presence", definition:"Is fully conscious and present with the client, employing a style that is open, flexible, grounded and confident", group:"Co-creating the relationship", summary:"Pay attention to what's happening with the client. Give them time to think, even when you don't know what comes next."},
    {id:6, title:"Listens Actively", definition:"Focuses on what the client is and is not saying to fully understand what is being communicated in the context of the client systems and to support client self-expression", group:"Communicating effectively", summary:"Follow the client's words and context. Check what they mean before relying on your interpretation."},
    {id:7, title:"Evokes Awareness", definition:"Facilitates client insight and learning by using tools and techniques such as powerful questioning, silence, metaphor or analogy", group:"Communicating effectively", summary:"Help the client explore their thinking and see things differently. Share what you notice without insisting that you're right."},
    {id:8, title:"Facilitates Client Growth", definition:"Partners with the client to transform learning and insight into action. Promotes client autonomy in the coaching process.", group:"Cultivating learning and growth", summary:"Help the client use what they've learned and choose their own next steps. Ask what support they want and how they'll follow through."}
  ],
  examExamples: {
    1:[
      {text:"When a sponsor asks what the client discussed, the coach checks the confidentiality agreement and relevant legal limits before sharing anything.",refs:["1.05"]},
      {text:"A client asks for an expert recommendation. The coach explains how that differs from coaching before agreeing on how to proceed.",refs:["1.06"]},
      {text:"The coach uses respectful language that fits the client's background and checks unfamiliar terms instead of assuming what they mean.",refs:["1.02","1.03"]}
    ],
    2:[
      {text:"The coach notices they want to push their own solution and returns to what matters to the client.",refs:["2.04","2.10"]},
      {text:"When the coach feels frustrated, they manage their response so it doesn't take over the conversation.",refs:["2.06"]},
      {text:"The client chooses a path the coach wouldn't choose. The coach stays curious and respects that it's the client's decision.",refs:["2.01","2.09"]}
    ],
    3:[
      {text:"At the start, the coach asks what the client wants from this session and checks that they've understood it in the client's own words.",refs:["3.06"]},
      {text:"The client wants clarity. The coach asks how they'd know they had it by the end of the session.",refs:["3.08"]},
      {text:"Another concern comes up. The coach asks whether the client wants to change the focus and checks their agreement again.",refs:["3.09","3.12"]}
    ],
    4:[
      {text:"The coach takes the client's concern seriously and gives them room to explain it.",refs:["4.05"]},
      {text:"When the client asks for a slower pace, the coach adjusts rather than defending their usual style.",refs:["4.02"]},
      {text:"Before assuming what an opportunity means, the coach asks about the client's circumstances and values.",refs:["4.01"]}
    ],
    5:[
      {text:"The client asks for thinking time, and the coach allows the pause without adding another question.",refs:["5.07"]},
      {text:"The coach doesn't yet know where the conversation is going. They stay curious instead of rushing to explain it.",refs:["5.02","5.06"]},
      {text:"During an emotional moment, the coach notices their own reaction and handles it so they can keep paying attention to the client.",refs:["5.01","5.04"]}
    ],
    6:[
      {text:"The coach briefly repeats back what they've heard and asks whether they've understood the client correctly.",refs:["6.02"]},
      {text:"A client calls a decision risky. The coach asks what the risk means in the client's circumstances.",refs:["6.01"]},
      {text:"When it sounds as though the client has more to say about a concern, the coach asks about it before moving to a solution.",refs:["6.03"]}
    ],
    7:[
      {text:"The coach asks what a belief means to the client and how it shapes their thinking.",refs:["7.03","7.08"]},
      {text:"The coach offers an observation as a possibility and asks what the client thinks of it. They let it go if it doesn't fit.",refs:["7.11"]},
      {text:"The coach asks the client to think of possible ways forward and what they'd be willing or able to try.",refs:["7.09"]}
    ],
    8:[
      {text:"When the client realizes something new, the coach asks how they want to use it in their life or work.",refs:["8.01"]},
      {text:"With the coach's help, the client chooses their next step and how to keep themselves on track.",refs:["8.02","8.03"]},
      {text:"Before closing, the coach asks what support the client may need and what could get in the way of their chosen step.",refs:["8.05","8.09"]}
    ]
  },
  questions: [
    {id:"case-sponsor-request", label:"A sponsor asks for more", c:1, refs:["1.01","1.05"], also:[{c:3,refs:["3.03"]}],
      prompt:"The agreement allows a sponsor to receive attendance and agreed goals, not session content. The sponsor asks for 'just a broad theme' to help support the client. No legal disclosure duty applies here. What is the strongest next response?", options:[
        ["Offer a general theme without names or examples.","A broad theme is still session content. Removing examples does not bring it within this agreement.","less"],
        ["Explain the sharing boundary and invite the client to choose whether they want to discuss additional sharing.","This addresses the request honestly while keeping any change in sharing client-owned. No extra content is disclosed first.","strongest"],
        ["Share only attendance and agreed goals, then ask what support the sponsor can offer within that boundary.","This respects the existing agreement and earns credit. It handles permitted support, but leaves the new request for themes unresolved.","reasonable"],
        ["Ask the client whether a joint conversation about support would be useful.","This can preserve client choice and earns credit. The sponsor still needs a clear response about the current sharing boundary.","reasonable"]
      ], answer:1, takeaway:"The new request does not change the agreement. Clarify the boundary before considering additional sharing with the client."},
    {id:"case-two-roles", label:"Two professional roles", c:1, refs:["1.06"], also:[{c:3,refs:["3.01","3.02"]}],
      prompt:"You offer coaching and, separately, product consulting. This session was agreed as coaching. A client planning a launch asks, 'Which launch structure would you recommend from your experience?' What fits best before responding to that request?", options:[
        ["Ask what they hope a recommendation would help them decide.","This explores the need behind the request and earns credit. Clarifying the professional role is still needed before giving a consulting recommendation.","reasonable"],
        ["Walk through your usual launch framework and ask which parts resonate.","A framework may be useful, but the client asked for your expert recommendation. The role and scope have not yet been clarified.","less"],
        ["Explore what relying on an expert would mean about their confidence.","That may be useful if the client wants it. Here it adds a personal interpretation before understanding their request for expertise.","less"],
        ["Clarify whether they want to change to consulting and agree what that would involve.","The request may call for another role. Naming that distinction lets the client make an informed choice before advice is offered.","strongest"]
      ], answer:3, takeaway:"Expert information can have a place. Make the role and agreement clear rather than disguising consulting as a coaching question."},
    {id:"case-summary-tool", label:"A new summary tool", c:1, refs:["1.05"], also:[{c:2,refs:["2.02"]}],
      prompt:"A client wants a session summary. You are considering a new cloud transcription tool whose retention and access terms you have not checked. The client says, 'I'm fine with tools.' What is the strongest next step?", options:[
        ["Check the tool's data handling and the agreement, then explain the proposed use before seeking informed permission.","General comfort with tools does not settle who can access a recording or how it is retained. This checks the proposed use before any upload.","strongest"],
        ["Use the tool after removing names from the recording.","Voices and contextual details may still identify people. Removing names does not resolve the unknown data handling.","less"],
        ["Offer a manually prepared summary under the existing agreement.","This avoids the unreviewed tool and earns credit. It meets the summary need, though it does not establish whether the proposed tool could be used appropriately.","reasonable"],
        ["Have the client upload the recording from their own account.","Changing who clicks Upload does not explain the tool's risks or resolve the coach's part in the proposed use.","less"]
      ], answer:0, takeaway:"Understand and explain a tool's handling of client information before using it. An appropriate manual alternative can also meet the client's need."},
    {id:"case-changing-support", label:"The support needed changes", c:1, refs:["1.06","1.07"], also:[{c:4,refs:["4.04"]}],
      prompt:"Over several weeks, a client reports difficulty managing ordinary daily activities. They now ask to use performance-coaching sessions to work through painful past experiences. There is no stated immediate danger. What fits best?", options:[
        ["Keep the agreed performance focus and choose a smaller, more achievable task.","A smaller task can help in some circumstances. Here it leaves the changed support need and scope unaddressed.","less"],
        ["Explore the past experiences in detail to understand the cause of the difficulty.","Listening matters, but this begins work that may exceed the coaching role before clarifying appropriate support.","less"],
        ["Acknowledge the changed need, discuss coaching's limits and explore appropriate professional support with them.","This responds to what has changed without diagnosing the client. It also allows an informed discussion of whether coaching remains useful alongside other support.","strongest"],
        ["Pause performance work and offer help finding suitable support, with the client's agreement.","This recognizes the scope concern and earns credit. A fuller conversation about what support they want and what coaching can still offer would strengthen it.","reasonable"]
      ], answer:2, takeaway:"A change in the client's needs calls for a scope conversation and appropriate support, not a diagnosis or an automatic assumption that all emotion is outside coaching."},
    {id:"case-coachs-preference", label:"A preference in the room", c:2, refs:["2.03","2.04","2.10"],
      prompt:"After a career session, you notice your questions repeatedly returned to a promotion, although the client was exploring a smaller role. You value rapid career progression. What would best help you learn from this?", options:[
        ["Ask the client for feedback on the usefulness of the session.","Client feedback can help and earns credit. It is one perspective; your own repeated steering also needs reflection.","reasonable"],
        ["Review where your preference shaped the questions and seek reflective support if needed.","This examines the coach's contribution rather than treating the client's choice as the problem. It supports learning that can change future behavior.","strongest"],
        ["Prepare a more neutral career questionnaire for the next session.","A questionnaire may help organize inquiry. It can still carry the same assumptions if your preference remains unexamined.","less"],
        ["Consider which question could have made the promotion feel more attainable.","This continues to favor the promotion rather than learning how your preference affected the client's exploration.","less"]
      ], answer:1, takeaway:"Look at how your own thinking shaped the conversation. A new question format alone does not resolve an unexamined preference."},
    {id:"case-before-session", label:"Before the next session", c:2, refs:["2.06","2.07","2.08"], also:[{c:5,refs:["5.04"]}],
      prompt:"Twenty minutes before a session, you are still replaying an upsetting disagreement after a brief pause. You are unsure you can give the client your attention. What is the strongest preparation choice?", options:[
        ["Use the remaining time to settle yourself and assess readiness honestly; contact the client if you cannot be present.","This takes responsibility for preparation and emotional regulation without assuming that having an emotion automatically makes coaching impossible.","strongest"],
        ["Begin on time and rely on the client's topic to shift your attention.","The session might distract you, but the client should not carry responsibility for restoring the coach's readiness.","less"],
        ["Arrange a reschedule if you judge that you cannot offer your usual attention.","This can protect the quality of the work and earns credit. It is less complete as a preparation approach because the remaining opportunity to assess and regulate is not considered.","reasonable"],
        ["Open with the client's recent successes to create a more positive atmosphere.","That opening could serve a client in another session. Here it is chosen to change the coach's mood rather than for the client's purpose.","less"]
      ], answer:0, takeaway:"Prepare for the client with an honest assessment of your capacity. Emotional regulation and appropriate help are part of the coach's ongoing practice."},
    {id:"case-learning-tool", label:"A tool promises a rating", c:2, refs:["2.02","2.03","2.08"],
      prompt:"A new coach-development tool claims its preferred question sequence demonstrates every competency. You want to use it to improve your work, but have not checked that claim. What is the strongest approach?", options:[
        ["Compare its ratings with your own impressions and adopt it where they agree.","Agreement with your own impressions can repeat the same blind spots. It does not establish that the tool's claims are sound.","less"],
        ["Use its sequence as a consistent baseline for all clients.","Consistency can help learning, but an unverified sequence may turn coaching into a script that does not fit each client.","less"],
        ["Use it to generate reflection topics while withholding judgment about its ratings.","This treats its output cautiously and earns credit. Checking the claim against authoritative guidance and informed feedback would make the learning approach stronger.","reasonable"],
        ["Check its claims against the official model and seek informed feedback before relying on its ratings.","This combines current learning with critical reflection and outside support. A tool's confidence is not evidence that its assessment is valid.","strongest"]
      ], answer:3, takeaway:"Treat learning tools critically. Useful reflection prompts and validated assessment claims are different things."},
    {id:"case-family-consultation", label:"Consulting family first", c:2, refs:["2.01","2.04","2.09"], also:[{c:4,refs:["4.01"]}],
      prompt:"A client wants to consult family before choosing a role. You notice you are interpreting this as avoidance, although the client has said family involvement matters to them. What is the strongest move?", options:[
        ["Ask what they would like to discuss with family before choosing.","This follows the client's plan and earns credit. It may not address the assumption already shaping your listening.","reasonable"],
        ["Invite an experiment in making this choice independently.","An independence experiment could be useful if the client wanted it. Here it favors the coach's interpretation of autonomy.","less"],
        ["Notice your assumption and ask what consulting family means in this decision.","This opens inquiry into the client's context while loosening the coach's unsupported interpretation. Consulting others can itself be a chosen action.","strongest"],
        ["Help draft a message asking family to approve the choice.","The client said consult, not seek approval. This adds another assumption while appearing to follow their plan.","less"]
      ], answer:2, takeaway:"Client responsibility does not require solitary decision-making. Stay curious about the client's chosen relationships and your own assumptions."},
    {id:"case-two-questions", label:"Leaving with two questions", c:3, refs:["3.06","3.07","3.08"], also:[{c:7,refs:["7.03"]}],
      prompt:"A client exploring a role offer says they do not want to decide today. They would leave satisfied with two questions to ask about the role. You have confirmed that outcome. What fits best now?", options:[
        ["What would clarity look like at the end of today?","That is useful when success is unclear. The client has already given a concrete indicator and you have confirmed it.","less"],
        ["What needs our attention to help you leave with those two questions?","This builds on the agreement and invites the client to identify what must be addressed to achieve it.","strongest"],
        ["What is the first question you might ask?","This begins practical work toward the agreed result and earns credit. It moves ahead without checking what the client believes needs attention first.","reasonable"],
        ["What would accepting the role say about who you are?","Identity may matter later. This directs exploration toward accepting when the client has deliberately chosen information-gathering today.","less"]
      ], answer:1, takeaway:"Once the outcome is clear, help the client identify what they need to address. Repeating an answered agreement question can interrupt useful work."},
    {id:"case-late-new-topic", label:"A new concern near the end", c:3, refs:["3.09","3.10","3.12"], also:[{c:5,refs:["5.01"]}],
      prompt:"Eight minutes remain in a session focused on preparing a conversation with a manager. The client says a newly noticed concern about belonging feels more important now. What is the strongest next response?", options:[
        ["Follow the belonging concern with a question about their earliest experience of it.","The new concern deserves attention. This opens a large inquiry without agreeing a workable focus for the time remaining.","less"],
        ["Help finish the manager-conversation plan before addressing belonging next time.","That would fit if the client chose it. The client has just indicated that the previous priority may have changed.","less"],
        ["Ask how the new concern connects with the conversation they were preparing.","This can integrate the threads and earns credit. It still assumes a connection is the best use of the remaining time.","reasonable"],
        ["Acknowledge the shift and agree what would be useful in the remaining eight minutes.","This respects the emerging priority and partners on the time and focus rather than automatically keeping or abandoning the original goal.","strongest"]
      ], answer:3, takeaway:"A new concern is an invitation to revisit the agreement. The client can choose a small new focus, integrate it, or retain the original one."},
    {id:"case-sponsored-goal", label:"Today's goal and the sponsor", c:3, refs:["3.04","3.06","3.12"], also:[{c:4,refs:["4.01"]}],
      prompt:"The engagement goal, agreed by client and sponsor, is better delegation. Today the client wants to understand why they keep accepting extra work. The link to delegation has not been discussed. What fits best?", options:[
        ["Explore how today's concern relates to the engagement and agree a useful focus with the client.","This keeps both levels of agreement visible without deciding that the sponsor's wording must control today's conversation.","strongest"],
        ["Begin by exploring what accepting extra work means to the client.","This takes the client's concern seriously and earns credit. Checking its place in the engagement would make the agreement clearer.","reasonable"],
        ["Reframe the concern as a delegation problem and ask what task they can hand over.","That could be relevant, but the coach supplies the connection and the task before hearing how the client sees the concern.","less"],
        ["Set aside the engagement goal so the client can talk freely.","Room for expression matters. Quietly dropping an agreed engagement goal is different from revisiting it together.","less"]
      ], answer:0, takeaway:"An engagement goal and a session goal need not use identical words. Explore their relationship and revise agreements openly when needed."},
    {id:"case-working-definition", label:"What would useful mean?", c:3, refs:["3.06","3.08"],
      prompt:"A client wants to 'feel ready' for a difficult conversation. Asked what ready means, they give more background but no indicator of a useful session result. What is the strongest next question?", options:[
        ["What do you think the other person will say?","This adds useful background in some situations. It does not clarify what the client wants to be different when today's session ends.","less"],
        ["What feels most important about having this conversation?","This explores significance and earns credit. The indicator of a useful result remains unclear.","reasonable"],
        ["What would you notice by the end of today that would tell you you feel readier?","This makes the broad phrase answerable without choosing a result or requiring a numerical measure.","strongest"],
        ["Would practicing your opening sentence give you the confidence you need?","A rehearsal might help, but this proposes a method and defines readiness as confidence before the client has done so.","less"]
      ], answer:2, takeaway:"Clarify the client's own indicator of usefulness. Readiness might mean a question, a feeling, a decision or something else."},
    {id:"case-rejected-reflection", label:"A reflection does not fit", c:4, refs:["4.02","4.05","4.06"], also:[{c:6,refs:["6.02"]}],
      prompt:"You reflect that a client sounds disappointed about a move. They reply, 'Relieved, actually. People keep expecting me to be disappointed.' What fits best?", options:[
        ["What is the relief like for you?","This accepts their correction and earns credit. Acknowledging your mistaken reflection first would also address their experience of being misread.","reasonable"],
        ["Thank you for correcting me. I got that wrong. What would you like me to understand about the relief?","This openly accepts the correction and gives the client room to describe their own experience without defending the coach's interpretation.","strongest"],
        ["Could disappointment and relief both be present?","Mixed feelings are possible, but introducing disappointment again immediately can privilege your interpretation over their correction.","less"],
        ["What will you do with the relief?","That may fit later. It moves to use of the feeling before acknowledging the correction or understanding what they want you to hear.","less"]
      ], answer:1, takeaway:"Welcome correction as part of the relationship. The client does not need to persuade the coach that their own experience is real."},
    {id:"case-name-the-effort", label:"An effort worth noticing", c:4, refs:["4.03","4.04"], also:[{c:8,refs:["8.08"]}],
      prompt:"A client says they asked a colleague for help despite worrying they would look incapable. They describe it as a small step and are still uncertain. What is the strongest acknowledgement?", options:[
        ["You are becoming a confident leader.","This assigns an identity and a level of confidence the client has not claimed. It may make uncertainty harder to express.","less"],
        ["How can you repeat that step next week?","This may support follow-through, but it skips acknowledging the effort they have just described.","less"],
        ["What made it possible to ask this time?","This explores an actual change and earns credit. It is an inquiry rather than a direct acknowledgement of their effort.","reasonable"],
        ["You asked for help while still feeling unsure. What is it like to notice that?","This recognizes the client's specific work without approving their decision or replacing their uncertainty with praise.","strongest"]
      ], answer:3, takeaway:"Acknowledge what the client actually did. Specific recognition can leave room for uncertainty and for their own meaning."},
    {id:"case-communication-style", label:"A different pace", c:4, refs:["4.01","4.02","4.05"], also:[{c:5,refs:["5.07"]}],
      prompt:"A client says they think more clearly when they can jot a few words before answering. Your usual style is a flowing spoken conversation. They suggest short writing pauses. What fits best?", options:[
        ["Agree a way to use writing pauses and check with them how the pace is working.","This takes the suggestion seriously and adapts the coaching in partnership rather than treating one communication style as the standard.","strongest"],
        ["Offer a pause now and invite them to make a note.","This responds to the immediate request and earns credit. Agreeing how to use that approach throughout the conversation would make the adaptation clearer.","reasonable"],
        ["Ask what makes spontaneous answers difficult for them.","That could become relevant if they want to explore it. At this moment it risks treating a stated preference as a problem to explain.","less"],
        ["Send written questions before the next session instead.","Preparation may be useful, but it does not respond to the requested pacing of the session already underway.","less"]
      ], answer:0, takeaway:"Adapt with the client. A preferred communication style does not need to become a coaching problem before it is respected."},
    {id:"case-context-of-no", label:"What saying no could cost", c:4, refs:["4.01","4.04","4.05"], also:[{c:6,refs:["6.01"]}],
      prompt:"A client says speaking directly to a senior colleague could carry real professional consequences. They want to find a workable response, and do not describe the issue as simply a confidence problem. What fits best first?", options:[
        ["What would a more confident version of you say?","This can be useful in some contexts. Here it narrows the concern to confidence before understanding the consequences the client named.","less"],
        ["What wording could make the message less confrontational?","This is a practical possibility and earns credit. It assumes wording is the main constraint before the context is understood.","reasonable"],
        ["What do I need to understand about the possible consequences for you?","This takes their circumstances seriously and lets the client describe the risks without making the coach's preferred directness the goal.","strongest"],
        ["What belief about seniority might you be ready to challenge?","A belief may matter, but this can recast a real contextual constraint as something inside the client before checking it.","less"]
      ], answer:2, takeaway:"Respect the client's context before inviting a challenge. Practical constraints and personal beliefs can both matter, and neither should be assumed."},
    {id:"case-thinking-space", label:"An unfinished thought", c:5, refs:["5.01","5.06","5.07"],
      prompt:"After a question, a client says, 'There is something there... let me stay with it.' They look thoughtful and continue making brief notes. There is ample time. What fits best?", options:[
        ["Offer a tentative reflection about what their hesitation might mean.","A reflection may help when invited. Here the client has asked to stay with their own emerging thought.","less"],
        ["Remain attentive and leave space for them to continue.","This follows an explicit request for reflection and tolerates not yet knowing where the thought is going.","strongest"],
        ["Quietly say, 'Take the time you need,' then stop speaking.","This supports the request and earns credit. The extra reassurance may be unnecessary because they have already claimed the space.","reasonable"],
        ["Ask what they are noticing right now.","That is a useful present-focused question in many moments. In this one, another question interrupts the thinking they requested.","less"]
      ], answer:1, takeaway:"Space can be the most responsive move. An otherwise useful question is not automatically useful during a requested pause."},
    {id:"case-unexpected-direction", label:"An unexpected answer", c:5, refs:["5.01","5.02","5.06"], also:[{c:3,refs:["3.10"]}],
      prompt:"A client is exploring what makes a project worth continuing. You expected a decision, but they say, 'I don't know yet. I have just realized how much I enjoy the people.' They want to explore that. What fits best?", options:[
        ["What would enjoying the people imply for your decision?","This connects to the original concern and earns credit. It may hurry the exploration into a decision the client is not yet ready to make.","reasonable"],
        ["How could you preserve those relationships if you left?","That possibility may matter later, but it leans toward leaving before the client has understood what the relationships mean.","less"],
        ["What would you need to decide before we finish?","This returns to an assumed decision outcome when the client has just asked for a different kind of exploration.","less"],
        ["What would you like to understand about enjoying the people?","This stays curious about the client's emerging experience rather than making uncertainty a gap the coach must immediately close.","strongest"]
      ], answer:3, takeaway:"Follow a useful emerging thread without rushing to fill uncertainty. A decision can follow understanding rather than precede it."},
    {id:"case-emotional-moment", label:"An emotional moment", c:5, refs:["5.01","5.04","5.05"], also:[{c:4,refs:["4.04","4.05"]}],
      prompt:"While discussing a missed opportunity, a client becomes tearful and says, 'I want to talk about it. I don't need you to fix it.' You notice a strong urge to reassure them. What fits best?", options:[
        ["Settle your own urge to fix, stay attentive and allow them to lead what they want to say.","This regulates the coach's response while respecting the client's clear request. Emotion alone is not a reason to abandon coaching.","strongest"],
        ["Reflect, 'This feels important,' and ask what they would like you to understand.","This can support expression and earns credit. It adds an invitation where simply staying with the client may be enough.","reasonable"],
        ["Ask what positive learning might come from the missed opportunity.","Learning may emerge later. Searching for a positive meaning now can move away from the experience they asked to express.","less"],
        ["Offer a short grounding exercise to help them regain composure.","An agreed exercise can help some clients. Here it assumes the emotion needs changing before the client can continue.","less"]
      ], answer:0, takeaway:"Manage your own response so the client's emotion can be expressed. Support does not require changing the feeling or finding an immediate positive meaning."},
    {id:"case-coachs-plan", label:"The planned question", c:5, refs:["5.01","5.03","5.06"], also:[{c:7,refs:["7.07"]}],
      prompt:"You prepared a question about values. In the session, the client notices a connection for themselves and begins explaining it with energy. It relates to the agreed outcome. What fits best?", options:[
        ["Ask the prepared values question before the thought becomes too detailed.","The question may have been well chosen in preparation. Asking it now could interrupt relevant learning already emerging.","less"],
        ["Briefly reflect the connection and invite them to continue.","This can support their exploration and earns credit. If they are already speaking clearly, the reflection may not be needed yet.","reasonable"],
        ["Let them develop the connection and respond to what emerges.","This follows the client's actual process rather than the coach's prepared sequence while retaining the agreed direction.","strongest"],
        ["Move to a next-step question to make use of the insight.","Using learning matters, but the client is still discovering what the connection means. Action design is premature in this moment.","less"]
      ], answer:2, takeaway:"Preparation should support responsiveness. When the client is developing relevant insight, the planned question can wait."},
    {id:"case-word-meaning", label:"A word with two meanings", c:6, refs:["6.01","6.02","6.03"], also:[{c:7,refs:["7.03"]}],
      prompt:"A client says they want a 'stable' role. Earlier they mentioned both predictable income and freedom to change projects. You do not yet know what stable means to them. What fits best?", options:[
        ["Which role would give you the most predictable income?","Income is one named concern, but selecting it as the meaning of stable excludes the other thread before checking.","less"],
        ["When you say stable, what would that mean in your life?","This uses the client's word and opens its meaning in their context without choosing between income and flexibility for them.","strongest"],
        ["I heard both predictable income and room to change projects. How do those fit together for you?","This checks a relevant relationship and earns credit. Asking about stable more openly leaves room for meanings beyond the two examples.","reasonable"],
        ["What would help you become comfortable with less stability?","This assumes they should change their relationship to stability before understanding what they mean by it.","less"]
      ], answer:1, takeaway:"A familiar word may carry a personal meaning. Explore that meaning before choosing a problem or solution."},
    {id:"case-tone-and-words", label:"Words and a change in energy", c:6, refs:["6.04","6.05"], also:[{c:4,refs:["4.05"]}],
      prompt:"In a video session, a client says, 'I'm excited about the move,' then lowers their voice and looks away. You can observe the change but do not know its meaning. What fits best?", options:[
        ["What worries you about the move?","Worry is possible, but this supplies the meaning of the observed change rather than asking the client.","less"],
        ["What are you most excited about?","This follows their stated words and earns credit. It may miss the change in expression that could add to understanding.","reasonable"],
        ["What would help you feel more confident about moving?","This moves to improving confidence without establishing whether confidence is part of the client's experience.","less"],
        ["You said excited, and your voice became quieter. What is happening for you now?","This offers an observable change without labeling it and invites the client to provide the meaning.","strongest"]
      ], answer:3, takeaway:"Integrate words and observable expression without assuming that a quieter voice means fear, doubt or any other particular feeling."},
    {id:"case-check-summary", label:"Two concerns in one story", c:6, refs:["6.02","6.03"],
      prompt:"A client describes workload, a colleague's request and a sense of having agreed too quickly. They pause and say, 'That's most of it.' You are unsure whether the central concern is time or the way they said yes. What fits best?", options:[
        ["I heard limited time and discomfort about how you agreed. What have I missed or misunderstood?","This checks understanding and leaves room for correction or something not yet said before the coach chooses the focus.","strongest"],
        ["Which of those concerns would you like to work on first?","This returns choice to the client and earns credit. Checking your understanding first would reduce the chance of choosing between incomplete interpretations.","reasonable"],
        ["What would a workable schedule look like?","That may help if time is the focus, but it selects one concern before the ambiguity is resolved.","less"],
        ["What makes it difficult for you to say no?","That could become relevant, but the client has described one agreement. This turns it into a recurring personal difficulty before checking.","less"]
      ], answer:0, takeaway:"A short summary can clarify the client's meaning without turning it into the coach's preferred problem."},
    {id:"case-across-sessions", label:"A pattern across sessions", c:6, refs:["6.01","6.06"], also:[{c:7,refs:["7.11"]}],
      prompt:"Across three sessions, a client describes feeling capable when preparing alone and less certain when presenting to a committee. Today they want to understand the difference. What fits best?", options:[
        ["What presentation technique could give you more confidence?","Technique may help, but the client wants to understand a difference that may involve more than presenting skills.","less"],
        ["What is different for you when the committee is there?","This explores the requested distinction and earns credit. Bringing in the repeated pattern could give them more context to consider.","reasonable"],
        ["Several times you've described confidence alone and uncertainty with the committee. What do you make of that difference?","This draws on an actual repeated pattern and invites their meaning without assigning a cause.","strongest"],
        ["What does needing the committee's approval tell you about yourself?","The client has not said approval is the issue. That interpretation may narrow the exploration before they describe the difference.","less"]
      ], answer:2, takeaway:"Use patterns you have actually heard to support understanding. The pattern is an observation, not proof of its cause."},
    {id:"case-who-and-what", label:"Doing the task, being the person", c:7, refs:["7.03","7.04","7.08"], also:[{c:6,refs:["6.01"]}],
      prompt:"A client already has a workable presentation plan. They say, 'The slides are ready. I keep thinking that if I need notes, I'm not a real expert.' They want to explore that thought. What fits best?", options:[
        ["How could you reduce the number of notes?","That addresses the task by accepting the premise that needing notes is the problem, rather than examining the thought they named.","less"],
        ["What counts as a real expert to you, and where do notes fit in that?","This explores the client's standard and the link they are making. The agreed need is about their interpretation of themselves, not another slide improvement.","strongest"],
        ["When have notes helped you present well?","This offers evidence that may widen their thinking and earns credit. It focuses more on how notes work than on the meaning of being an expert.","reasonable"],
        ["What would convince the audience you are an expert?","This could help in a different conversation. Here it shifts to proving expertise to others rather than exploring the client's own standard.","less"]
      ], answer:1, takeaway:"When the task is prepared and the client wants to examine a self-judgment, explore the meaning they attach to it. Do not assume a better task plan will resolve it."},
    {id:"case-task-is-the-goal", label:"A practical goal is enough", c:7, refs:["7.01","7.07","7.09"], also:[{c:3,refs:["3.10"]}],
      prompt:"A client has explored why a project matters and now wants to leave with options for an achievable first step. They say, 'I understand my motivation. I need to think through what I can actually try this week.' What fits best?", options:[
        ["Who would you become if you followed through?","Identity exploration can help when wanted. Here it pulls away from the practical outcome the client has clearly chosen.","less"],
        ["What might not following through mean about you?","This introduces a self-judgment where the client asked to generate workable options.","less"],
        ["What resources already available to you could make a first step easier?","This explores feasibility and earns credit. Generating the possible steps first would give the resource inquiry a clearer target.","reasonable"],
        ["What are a few first steps you would be willing and able to try this week?","This invites client-generated possibilities within their real constraints and serves the requested task-focused outcome.","strongest"]
      ], answer:3, takeaway:"The 'who' does not always outrank the 'what'. Practical exploration can be the strongest fit when it serves the client's chosen outcome."},
    {id:"case-grounded-observation", label:"An observation to test", c:7, refs:["7.08","7.11"], also:[{c:6,refs:["6.02"]}],
      prompt:"A client has twice called an assignment urgent, then said it is not their priority. They want to understand why they keep accepting similar work. What fits best?", options:[
        ["You've called this urgent and also not your priority. What do you make of that?","This offers a specific observation that may open insight, while leaving the client free to give it a different meaning.","strongest"],
        ["What makes these assignments hard to decline?","This explores a relevant factor and earns credit. It does not use the distinction already emerging in the client's own words.","reasonable"],
        ["What rule would help you protect your priorities?","A rule may be useful after understanding the pattern. This moves toward a solution before exploring the repeated acceptance.","less"],
        ["What would it take to treat your own priorities as more important?","This assumes the issue is ranking personal priorities above others, rather than allowing the client to explain the distinction.","less"]
      ], answer:0, takeaway:"Offer a grounded distinction as something to explore. Let the client decide whether it reveals anything useful."},
    {id:"case-more-than-two", label:"More than two possibilities", c:7, refs:["7.04","7.09","7.10"],
      prompt:"A client says their only choices are to accept a full role change or remain exactly where they are. They want to explore possibilities and have not checked whether the role can be shaped. What fits best?", options:[
        ["Which of the two choices better expresses your values?","Values may help evaluate options, but this accepts the two-choice frame the client wants to explore beyond.","less"],
        ["What would make staying where you are easier?","That can support one option, but it starts improving staying rather than broadening the possibilities.","less"],
        ["What other arrangements might be possible before you choose?","This invites ideas beyond the current frame without supplying the coach's preferred compromise or assuming one is available.","strongest"],
        ["What information would help you test whether those are the only choices?","This examines the frame in a practical way and earns credit. Generating possible arrangements may open a wider range before the client chooses what to test.","reasonable"]
      ], answer:2, takeaway:"Help the client widen a frame without promising that a particular alternative exists or steering them to a compromise."},
    {id:"case-insight-into-use", label:"Putting a discovery to use", c:8, refs:["8.01","8.02","8.03"], also:[{c:7,refs:["7.06"]}],
      prompt:"A client realizes they work better after asking for a clear brief. They say, 'I'd like to use that on the next assignment.' There is time to design their follow-through. What fits best?", options:[
        ["What does that discovery say about the kind of person you are?","Self-learning can matter, but the client has just asked to use a discovery on a particular assignment.","less"],
        ["How would you like to put that learning into practice on the next assignment?","This moves from the client's insight to client-designed use without prescribing a script or an accountability method.","strongest"],
        ["What might make asking for the brief easier next time?","This explores support for the intended change and earns credit. Letting the client define the action first would make the support more specific.","reasonable"],
        ["Would sending a standard briefing form solve this for you?","A form may be useful, but it introduces the coach's chosen implementation before the client designs what fits.","less"]
      ], answer:1, takeaway:"Help the client choose how to use their own learning. A useful tool can follow that choice rather than determine it."},
    {id:"case-support-and-barriers", label:"An action meets real life", c:8, refs:["8.02","8.04","8.05"],
      prompt:"A client chooses to spend half an hour reviewing a draft on Friday. They mention that childcare often changes their plans and want the experiment to teach them what is workable. What fits best?", options:[
        ["What would you learn if you protected that half hour regardless of interruptions?","This narrows the experiment to protecting the time and can overlook a constraint the client has named.","less"],
        ["How will you hold yourself accountable for Friday?","Accountability can help, but the immediate issue is whether the plan fits the client's circumstances.","less"],
        ["Would a daily reminder help you keep the appointment?","A reminder is one possible tool. It does not address childcare or what the client wants to learn from the experiment.","less"],
        ["What support or alternative would make the experiment workable if Friday changes?","This follows the client's chosen action, considers barriers and supports learning rather than treating changed circumstances as failure.","strongest"]
      ], answer:3, takeaway:"Design follow-through around the client's real circumstances and learning purpose. This moment calls for feasibility before reminders or accountability."},
    {id:"case-client-accountability", label:"Choosing accountability", c:8, refs:["8.02","8.03"],
      prompt:"A client has chosen a small experiment and says formal report-backs make them focus on pleasing the coach. They would prefer to notice what they learn privately. What fits best?", options:[
        ["How would you like to notice and keep track of what you learn?","This lets the client design a method that serves their learning rather than the coach's need to receive a report.","strongest"],
        ["Invite them to reflect privately and revisit whether they want to discuss the learning next time.","This respects the preference and earns credit. Inviting them to design the noticing method would make the follow-through clearer.","reasonable"],
        ["Offer a very brief email report so accountability feels less formal.","Less formal reporting is still reporting to the coach. It does not yet respond to the concern the client has identified.","less"],
        ["Explore what makes pleasing others important to them before agreeing an accountability method.","That may be useful if the client wants to explore it. Here it postpones respecting a clear preference while redirecting into a new personal inquiry.","less"]
      ], answer:0, takeaway:"Accountability can serve the client's learning without a report to the coach. A private reflection method can be a valid choice."},
    {id:"case-close-with-learning", label:"Closing without another task", c:8, refs:["8.06","8.08","8.09"], also:[{c:3,refs:["3.09"]}],
      prompt:"Two minutes remain. A client says today's useful result is understanding that they need more information before choosing. They want to leave action planning until later. What fits best?", options:[
        ["What is one action you can commit to before we close?","Action may follow later. Requiring one now changes the useful result and the preference the client has just stated.","less"],
        ["Would you like me to summarize the main points?","This offers a potentially useful close and earns credit. A client-led summary would better show what they want to carry away.","reasonable"],
        ["What would you like to take from today's learning, and how would you like to finish?","This supports integration and a partnered close within the available time, without making a new action the price of completion.","strongest"],
        ["What is the deeper reason you are not ready to choose?","That may open a large inquiry at the end and frames the client's stated information need as something else to explain.","less"]
      ], answer:2, takeaway:"Learning and a client-owned close can be enough for today. Respect the chosen outcome and the remaining time."}
  ],
  scenario: {
    title:"Taking on another project",
    intro:"A fictional client is weighing a new project. You've agreed to discuss it, but don't yet know what they want from today's session. Choose your reply at each turn. The client's replies are invented.",
    start:"opening",
    nodes:{
      opening:{c:3, refs:["3.06","3.08"], client:"They've asked me to lead another project. I keep going back and forth. I'd like to get clearer about it.", choices:[
        {text:"What would make this conversation useful to you today?", reaction:"I'd like to figure out what I need to ask before I decide. I don't want to decide today.", reason:"They want to work out what to ask, not decide today. Ask how they'll know they've worked that out, then check you agree on the session's goal.", next:"explore"},
        {text:"What would tell you this conversation had helped?", reaction:"I'd know which questions I still need to ask. I keep trying to force a yes or no before I have the information.", reason:"You're asking how they'll know the session has helped. Check you both understand what they want before moving on.", next:"explore"},
        {text:"Let's use today to decide whether you should accept.", reaction:"I'm not ready to decide. There are things I haven't asked about.", reason:"You decided the goal for them. They've said they need more information, so return to that.", next:"repair"}
      ]},
      repair:{c:3, refs:["3.06","3.12"], client:"I need to work out what's missing before I make a decision.", choices:[
        {text:"I got ahead of you. What would you like to understand by the end of our session?", reaction:"What I need to ask about the workload. And why I'm hesitating to ask.", reason:"You admit you got ahead of them and ask what they want. Their answer helps you agree on a better focus.", next:"explore"},
        {text:"Would focusing on the missing information be useful today?", reaction:"Yes. I want to look at the workload and why I haven't asked about it.", reason:"You're suggesting a new focus and asking if it fits. A yes-or-no question works for checking an agreement.", next:"explore"}
      ]},
      explore:{c:6, refs:["6.01","6.02","6.03"], client:"I don't know how much extra work it would be. I keep thinking I should be grateful they've asked me, so I don't ask about the workload.", choices:[
        {text:"What does 'I should be grateful' mean to you here?", reaction:"I worry that asking will sound unappreciative. I do want to know what I'm agreeing to, though.", reason:"You ask about 'grateful' instead of assuming why they won't ask. This can help you understand their concern and may help them see something new.", next:"close"},
        {text:"You want to know about the workload, and you're worried about how asking might come across. Is that right?", reaction:"Yes. Asking isn't refusing, is it? I've been treating them as if they're the same.", reason:"You check that you've understood and give them room to correct you. Repeating back what you heard can help as much as asking another question.", next:"close"},
        {text:"This sounds like people-pleasing. You need firmer boundaries.", reaction:"I don't think that label fits. I still need to know about the workload.", reason:"You label the problem and tell them what to do before checking what they mean. Accept the correction and return to what they want to understand.", next:"closeRepair"}
      ]},
      closeRepair:{c:8, refs:["8.03","8.05","8.09"], client:"I need to know more about the workload. I'm not ready to act yet, and we're nearly out of time.", choices:[
        {text:"I got that wrong. How would you like to finish today?", reaction:"I'd like to write down the information I need. I'll decide what to do with it later.", reason:"You admit you got it wrong and let them choose how to finish. They can act, think it over or leave the decision for another day.", next:null},
        {text:"Let's stay with the workload. What would help you think about it after today?", reaction:"Some time, and maybe a colleague who knows the project. I don't want a deadline yet.", reason:"You return to the workload and ask what would help them think it through. Respect their wish to leave the timing open and agree how to finish.", next:null},
        {text:"You're avoiding it again. Commit to asking tonight.", reaction:"That's not what I said I wanted. I'd like to stop here.", reason:"You push the same idea after they've rejected it, then tell them what to do. They've asked to stop; respect that and let them choose whether to act.", next:null}
      ]},
      close:{c:8, refs:["8.01","8.03","8.05","8.09"], client:"I can appreciate being asked and still ask about the workload. That helps. We're nearly out of time, and I'd like to do something with this.", choices:[
        {text:"How would you like to use what you've learned today?", reaction:"I'll draft two questions about the workload and decide when to send them. I'd like a colleague to check the wording.", reason:"They pick their own step and name someone who could help. If time allows, ask what support they need or what could get in the way, then agree how to finish.", next:null},
        {text:"Would you like to choose a next step now, or take some time to think first?", reaction:"I'd rather write down what I've learned before I choose an action.", reason:"They prefer to write down what they learned before choosing an action. Thinking it over is a valid next step. Follow their choice and agree how to finish.", next:null},
        {text:"Email the project lead tonight and report back to me tomorrow.", reaction:"Tonight won't work. I want to prepare my questions first.", reason:"You choose the task and set a deadline and check-in. Ask what would work for them and let them choose how to follow through.", next:null}
      ]}
    }
  }
};
